import {fitBoard} from './fit-board.mjs';
import {blockNetworkMap,componentEnvelope} from './block-visibility.mjs';
import {escapeHTML as esc} from './component-markings.mjs';
export const blockPalette={power:'#ffb72f',charge:'#ffb72f',control:'#55aaff',powerstage:'#ff647c',relay:'#ff647c',triac:'#ff647c',interface:'#bd8aff',radio:'#bd8aff',display:'#42d9c5',audio:'#42d9c5',storage:'#55aaff',protection:'#ff9d60',indicators:'#42d9c5'};
export function blockGroups(board){return (board.blocks||[]).map(b=>({...b,color:blockPalette[b.id]||b.color||'#a0adb9'}));}
export function matchingParts(board,query){const q=query.trim().toLowerCase();return board.elements.filter(e=>`${e.name} ${e.value||''} ${e.package}`.toLowerCase().includes(q));}
export function mountWorkstation(api){
 const host=document.createElement('section');host.className='boardWorkstation';document.querySelector('.viewer').prepend(host);
 host.innerHTML=`<div class="workstationTitle"><div><span class="studioKicker">MESA DE INSPECCIÓN</span><h2>Del conjunto al detalle.</h2></div><div class="wsQuickActions"><button id="wsFocus">Centrar bloque</button><button id="wsPlan">Plano PCB 2D ↗</button></div></div><details class="wsAdvanced"><summary>Buscar componentes, planos y encuadres</summary><div class="wsControls"><label>Localizar componente<input id="wsSearch" type="search" placeholder="U1, 10k, 0603, USB…" autocomplete="off"></label><label>Orientación por función<select id="wsBlocks"><option value="off">Acabado físico / colores de familia</option><option value="all">Todos los bloques funcionales</option></select></label><button id="wsSave">Guardar encuadre</button><button id="wsRestore">Volver a mi encuadre</button></div><div id="wsResults" class="wsResults" aria-label="Resultados de componentes"></div></details><div class="wsBottom"><div><div id="wsOriginal" class="wsOriginal"></div><div id="wsLegend" class="wsLegend"></div><div id="wsBlockDetail" class="wsBlockDetail" hidden></div><label class="wsShared"><input id="wsShared" type="checkbox"> Incluir redes compartidas (blancas discontinuas)</label><p id="wsNetworkSummary"></p><p id="wsStatus" role="status"></p><small>Girar: arrastrar · Desplazar: botón derecho o dos dedos · Acercar: rueda o pellizco · Doble clic: centrar la zona.</small></div><canvas id="wsMap" width="280" height="150" tabindex="0" aria-label="Minimapa de la placa. Pulsa para centrar una zona; Inicio centra la placa."></canvas></div>`;
 const $=id=>document.getElementById(id);let currentId='',active='off',selected='',saved={},mapBounds;
 try{saved=JSON.parse(api.storage.getItem('circuitlab-views-v19')||'{}');}catch{}
 const status=text=>$('wsStatus').textContent=text;
 function move(x,y,size=20,bottom=false){const {camera,controls,root}=api.scene();if(!camera||!controls||!root)return;const target=new api.THREE.Vector3(x+root.position.x,y+root.position.y,bottom?-1.3:1);controls.target.copy(target);camera.position.copy(target).add(new api.THREE.Vector3(size*.28,-size*.55,size*(bottom?-.85:.85)));controls.update();api.face?.(bottom);}
 function frame(elements){const {camera,controls,root}=api.scene();if(!camera||!controls||!root||!elements.length)return;const b=api.board(),boxes=elements.map(e=>componentEnvelope(b,e)),bounds=[Math.min(...boxes.map(a=>a[0])),Math.min(...boxes.map(a=>a[1])),Math.max(...boxes.map(a=>a[2])),Math.max(...boxes.map(a=>a[3]))],bottom=elements.every(e=>e.mirror);fitBoard(api.THREE,camera,controls,bounds,{bottom,height:elements.length===1?5:12,center:[(bounds[0]+bounds[2])/2+root.position.x,(bounds[1]+bounds[3])/2+root.position.y,0]});api.face?.(bottom);}
 function focus(ref){const b=api.board(),e=b.elements.find(x=>x.name===ref);if(!e)return;selected=ref;api.inspect(ref);frame([e]);status(`${e.name} · ${e.value||e.package} · ${e.pads.length} terminales · ${e.mirror?'cara inferior':'cara superior'}`);drawMap();}
 function results(){const b=api.board(),q=$('wsSearch').value,found=matchingParts(b,q);$('wsResults').innerHTML=(q?found.slice(0,20):[]).map(e=>`<button data-part="${esc(e.name)}"><b>${esc(e.name)}</b><span>${esc(e.value||e.package)}</span></button>`).join('');$('wsResults').querySelectorAll('[data-part]').forEach(btn=>btn.onclick=()=>focus(btn.dataset.part));if(q)status(found.length?`${found.length} coincidencias${found.length>20?' · mostrando las primeras 20':''}`:'No hay componentes que coincidan.');}
 function syncBlocks(){api.blocks(active,$('wsShared').checked);const nets=blockNetworkMap(api.board(),active,$('wsShared').checked),own=[...nets.values()].filter(n=>!n.shared).length,shared=[...nets.values()].filter(n=>n.shared).length;$('wsNetworkSummary').textContent=active==='off'?'Pulsa un bloque: componentes y pistas propias en color; el resto queda atenuado.':`${own} redes propias · ${shared} redes compartidas${$('wsShared').checked?' visibles en blanco':' ocultas del resaltado'}. El color identifica función, no tensión.`; $('wsBlocks').value=active;$('wsLegend').querySelectorAll('[data-function]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.function===active)));drawMap();renderBlockDetail();const b=api.board(),groups=blockGroups(b),known=new Set(groups.flatMap(g=>g.elements)),group=groups.find(g=>g.id===active);status(group?`${group.title}: ${group.reason||'Sigue las redes para comprobar la función.'}`:`${b.elements.length} componentes · ${b.pads.length} terminales · ${known.size} clasificados · ${b.elements.filter(e=>!known.has(e.name)).length} sin clasificar`);}
 function renderBlockDetail(){const b=api.board(),g=blockGroups(b).find(g=>g.id===active),host=$('wsBlockDetail');host.hidden=!g;if(!g){host.replaceChildren();return;}const parts=b.elements.filter(e=>g.elements.includes(e.name)),networks=blockNetworkMap(b,active,true);host.style.setProperty('--block-color',g.color);host.innerHTML=`<div class="blockDetailHead"><b>${esc(g.title)}</b><span>${parts.length} componentes</span></div><p>${esc(g.reason||g.clue||'Comprueba las conexiones en el plano y el visor.')}</p><details><summary>Localizar componentes y seguir redes</summary><div class="blockPartList">${parts.map(e=>`<button data-block-part="${esc(e.name)}"><b>${esc(e.name)}</b><span>${esc(e.value||e.package)}</span><small>${e.mirror?'Inferior':'Superior'}</small></button>`).join('')}</div><div class="blockNetList">${[...networks].map(([name,n])=>`<button data-block-net="${esc(name)}">${esc(name)} <small>${n.shared?'Compartida':'Propia'}</small></button>`).join('')}</div></details>`;host.querySelectorAll('[data-block-part]').forEach(btn=>btn.onclick=()=>focus(btn.dataset.blockPart));host.querySelectorAll('[data-block-net]').forEach(btn=>btn.onclick=()=>{api.net(btn.dataset.blockNet);status('Red seleccionada: '+btn.dataset.blockNet);});}
 function drawMap(){const b=api.board();if(!b)return;const c=$('wsMap'),ctx=c.getContext('2d');if(!ctx)return;const [x0,y0,x1,y1]=b.bounds,scale=Math.min(260/(x1-x0),130/(y1-y0)),ox=(280-(x1-x0)*scale)/2,oy=(150-(y1-y0)*scale)/2;mapBounds={x0,y1,scale,ox,oy};ctx.fillStyle='#071a24';ctx.fillRect(0,0,280,150);ctx.fillStyle='#124631';ctx.fillRect(ox,oy,(x1-x0)*scale,(y1-y0)*scale);const groups=blockGroups(b);for(const e of b.elements){const group=groups.find(g=>g.elements.includes(e.name));ctx.fillStyle=e.name===selected?'#fff':active==='off'?'#b0bfb8':group?group.color:'#687782';ctx.globalAlpha=active!=='off'&&active!=='all'&&group?.id!==active? .25:1;ctx.fillRect(ox+(e.x-x0)*scale-2,oy+(y1-e.y)*scale-2,4,4);}ctx.globalAlpha=1;const {controls,root}=api.scene();if(controls&&root){const x=ox+(controls.target.x-root.position.x-x0)*scale,y=oy+(y1-controls.target.y+root.position.y)*scale;ctx.strokeStyle='#fff';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.stroke();}}
 $('wsShared').onchange=syncBlocks;$('wsSearch').oninput=results;$('wsSearch').onkeydown=e=>{if(e.key==='Enter'){const found=matchingParts(api.board(),e.target.value);if(found[0])focus(found[0].name);}};
 $('wsBlocks').onchange=e=>{active=e.target.value;syncBlocks();};$('wsFocus').onclick=()=>{const b=api.board(),g=blockGroups(b).find(x=>x.id===active);if(!g){api.home();status('Elige un bloque concreto para acercarte a sus componentes.');return;}frame(b.elements.filter(e=>g.elements.includes(e.name)));};
 $('wsSave').onclick=()=>{const {camera,controls}=api.scene();if(!camera)return;saved[api.board().id]={position:camera.position.toArray(),target:controls.target.toArray()};try{api.storage.setItem('circuitlab-views-v19',JSON.stringify(saved));status('Encuadre guardado para esta placa en este navegador.');}catch{status('No se pudo guardar el encuadre.');}};
 $('wsRestore').onclick=()=>{const s=saved[api.board().id],{camera,controls}=api.scene();if(!s||!camera){status('Todavía no tienes un encuadre guardado de esta placa.');return;}camera.position.fromArray(s.position);controls.target.fromArray(s.target);controls.update();};
 $('wsMap').onclick=e=>{if(!mapBounds)return;const r=e.currentTarget.getBoundingClientRect(),{x0,y1,scale,ox,oy}=mapBounds;move(x0+((e.clientX-r.left)*280/r.width-ox)/scale,y1-((e.clientY-r.top)*150/r.height-oy)/scale,25,api.scene().camera?.position.z<0);};$('wsMap').onkeydown=e=>{if(e.key==='Home'){e.preventDefault();api.home();}};
 $('wsPlan').onclick=()=>openPCBPlan(api,focus,{block:active,shared:$('wsShared').checked});
 function refresh(){const b=api.board();if(!b)return;if(currentId!==b.id){currentId=b.id;active='off';selected='';$('wsSearch').value='';$('wsResults').replaceChildren();}const pages=b.schematicPages||{mosfet:1,logic:1,ardumoto:2}[b.id]||0;$('wsOriginal').innerHTML=Array.from({length:pages},(_,i)=>`<a href="reference/${b.id}-schematic-${i+1}.svg" target="_blank" rel="noopener noreferrer">Esquema CAD · hoja ${i+1} ↗</a>`).join('');const groups=blockGroups(b);$('wsBlocks').innerHTML='<option value="off">Acabado físico / colores de familia</option><option value="all">Todos los bloques funcionales</option>'+groups.map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('');$('wsBlocks').value=active;$('wsLegend').innerHTML='<button data-function="off">Acabado real</button><button data-function="all">Todos los bloques</button>'+groups.map(g=>`<button data-function="${esc(g.id)}" style="--block-color:${g.color}"><i style="background:${g.color}"></i>${esc(g.title)} <small>${g.elements.length}</small></button>`).join('')+'<span><i style="background:#7d8998"></i>Sin clasificar</span>';$('wsLegend').querySelectorAll('[data-function]').forEach(btn=>btn.onclick=()=>{active=btn.dataset.function;syncBlocks();});syncBlocks();}
 api.scene().controls?.addEventListener('change',drawMap);const dom=api.scene().renderer?.domElement;dom?.addEventListener('dblclick',e=>{const {camera,root,controls}=api.scene(),r=dom.getBoundingClientRect(),ray=new api.THREE.Raycaster();ray.setFromCamera(new api.THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.ray.intersectPlane(new api.THREE.Plane(new api.THREE.Vector3(0,0,1),0),new api.THREE.Vector3());if(hit)move(hit.x-root.position.x,hit.y-root.position.y,Math.max(9,camera.position.distanceTo(controls.target)*.55),camera.position.z<0);});refresh();return {refresh,focus,selectBlock(mode,shared=false){active=mode;$('wsShared').checked=shared;syncBlocks();}};
}
export function openPCBPlan(api,onPart,{block='off',shared=false}={}){
 const b=api.board(),dialog=document.createElement('dialog');dialog.className='pcbPlanDialog';dialog.innerHTML=`<div class="planDialogHead"><div><span class="studioKicker">PLANO DE IMPLANTACIÓN · COORDENADAS DEL MODELO</span><h2>${esc(b.title)}</h2></div><button aria-label="Cerrar plano">×</button></div><p>${b.representative||b.educational?'Diseño didáctico':'Trazado importado del CAD original'} · geometría y redes compartidas con el visor 3D. Rellenos de cobre no reconstruidos.</p><div class="pcbTools"><label>Capa<select id="pcbLayer">${(b.layers||[{id:1,name:'Superior'},{id:16,name:'Inferior'}]).map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></label><label>Red<select id="pcbNet"><option value="">Todas las redes</option>${b.nets.map(n=>`<option value="${esc(n.name)}">${esc(n.name)}</option>`).join('')}</select></label><button id="pcbPlus">＋</button><button id="pcbMinus">−</button><button id="pcbFit">Ajustar</button><label>Función<select id="pcbFunction"><option value="off">Acabado físico</option><option value="all">Todos los bloques</option>${blockGroups(b).map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('')}</select></label><label><input id="pcbBlocks" type="checkbox"> Bloques por color</label><label><input id="pcbShared" type="checkbox"> Redes compartidas</label><label><input id="pcbNames" type="checkbox" checked> Referencias</label></div><canvas id="pcbCanvas" width="1400" height="850" aria-label="Plano PCB. Arrastra para desplazar; rueda para ampliar; pulsa un pad para seleccionar su red."></canvas><p id="pcbInfo" role="status">Todas las capas se miran desde arriba; la inferior no está espejada. Pulsa un pad para seguir su red. Doble clic en un componente para inspeccionarlo en 3D.</p>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});
 const $=id=>dialog.querySelector('#'+id),canvas=$('pcbCanvas'),ctx=canvas.getContext('2d');let zoom=1,px=0,py=0,drag=null,moved=false;const [x0,y0,x1,y1]=b.bounds,base=Math.min(1300/(x1-x0),750/(y1-y0));const point=(x,y)=>[700+(x-(x0+x1)/2)*base*zoom+px,425-(y-(y0+y1)/2)*base*zoom+py];
 function draw(){const layer=Number($('pcbLayer').value),selected=$('pcbNet').value,mode=$('pcbBlocks').checked?$('pcbFunction').value:'off',functional=mode!=='off',groups=blockGroups(b),network=blockNetworkMap(b,mode,$('pcbShared').checked);const partColor=ref=>{const g=groups.find(g=>g.elements.includes(ref));return g&&(mode==='all'||g.id===mode)?g.color:'#33454b';};ctx.fillStyle='#071821';ctx.fillRect(0,0,1400,850);let [x,y]=point(x0,y1);ctx.fillStyle='#103e2e';ctx.fillRect(x,y,(x1-x0)*base*zoom,(y1-y0)*base*zoom);for(const n of b.nets){ctx.strokeStyle=n.name===selected?'#f8e979':selected?'#355b53':layer===1?'#f3b26b':'#62bbff';const membership=network.get(n.name);if(functional)ctx.strokeStyle=membership?.visible?(membership.shared?'#effaff':(blockGroups(b).find(g=>g.id===membership.group.id)?.color||membership.group.color)):'#243b37';if(n.name===selected)ctx.strokeStyle='#fff7b0';ctx.setLineDash(functional&&membership?.visible&&membership.shared?[7,5]:[]);ctx.lineCap='round';for(const w of n.wires){if(w.layer!==layer)continue;ctx.lineWidth=Math.max(.6,w.width*base*zoom);ctx.beginPath();api.arcPoints(w).forEach(([x,y],i)=>{const p=point(x,y);i?ctx.lineTo(...p):ctx.moveTo(...p);});ctx.stroke();}ctx.setLineDash([]);for(const via of n.vias){const p=point(via.x,via.y);ctx.strokeStyle=n.name===selected?'#fff49f':functional?(membership?.visible?(membership.shared?'#effaff':partColor(n.contacts[0]?.split('.')[0])):'#243b37'):'#d8b875';ctx.lineWidth=Math.max(.8,via.drill*base*zoom*.3);ctx.beginPath();ctx.arc(...p,Math.max(1,(via.diameter||via.drill*2)*base*zoom/2),0,Math.PI*2);ctx.stroke();}}
 for(const p of b.pads){if(!p.drill&&p.layer!==layer)continue;const q=point(p.x,p.y);ctx.save();ctx.translate(...q);ctx.rotate(-p.rot*Math.PI/180);ctx.fillStyle=selected===p.net?'#fff7b0':selected?'#64736b':'#d3ac62';if(functional&&selected!==p.net)ctx.fillStyle=partColor(p.element||p.id.split('.')[0]);if(p.drill){ctx.beginPath();ctx.arc(0,0,p.diameter*base*zoom/2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#061922';ctx.beginPath();ctx.arc(0,0,p.drill*base*zoom/2,0,Math.PI*2);ctx.fill();}else ctx.fillRect(-p.dx*base*zoom/2,-p.dy*base*zoom/2,p.dx*base*zoom,p.dy*base*zoom);ctx.restore();}
 if($('pcbBlocks').checked&&[1,16].includes(layer)){const groups=blockGroups(b);for(const e of b.elements){if(!!e.mirror!==(layer===16))continue;const g=groups.find(g=>g.elements.includes(e.name)),p=point(e.x,e.y),w=Math.max(6,(e.body?.[0]||3)*base*zoom),h=Math.max(6,(e.body?.[1]||2)*base*zoom);ctx.save();ctx.translate(...p);ctx.rotate(-e.rot*Math.PI/180);ctx.strokeStyle=partColor(e.name);ctx.fillStyle=partColor(e.name);ctx.globalAlpha=.25;ctx.fillRect(-w/2,-h/2,w,h);ctx.globalAlpha=1;ctx.lineWidth=3;ctx.strokeRect(-w/2,-h/2,w,h);ctx.restore();}}if($('pcbNames').checked&&[1,16].includes(layer)){ctx.fillStyle='#eefbff';ctx.font='14px ui-monospace,monospace';for(const e of b.elements){if(!!e.mirror!==(layer===16))continue;const q=point(e.x,e.y);ctx.fillText(e.name,q[0]+3,q[1]-7);}}ctx.fillStyle='#d6e7eb';ctx.font='18px ui-monospace';ctx.fillText(`${(x1-x0).toFixed(1)} × ${(y1-y0).toFixed(1)} mm · ${zoom.toFixed(1)}×`,24,32);}
 const coords=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*1400/r.width,(e.clientY-r.top)*850/r.height];};
 const zoomAt=(factor,c=[700,425])=>{const z=Math.max(.5,Math.min(35,zoom*factor)),f=z/zoom;px=c[0]-700-(c[0]-700-px)*f;py=c[1]-425-(c[1]-425-py)*f;zoom=z;draw();};
 canvas.onwheel=e=>{e.preventDefault();zoomAt(e.deltaY<0?1.15:1/1.15,coords(e));};canvas.onpointerdown=e=>{drag={p:coords(e),px,py};moved=false;canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;const q=coords(e);if(Math.hypot(q[0]-drag.p[0],q[1]-drag.p[1])>5)moved=true;px=drag.px+q[0]-drag.p[0];py=drag.py+q[1]-drag.p[1];draw();};canvas.onpointerup=e=>{if(!drag)return;drag=null;if(moved)return;const q=coords(e),layer=Number($('pcbLayer').value),nearest=b.pads.filter(p=>p.drill||p.layer===layer).map(p=>({p,d:Math.hypot(point(p.x,p.y)[0]-q[0],point(p.x,p.y)[1]-q[1])})).sort((a,b)=>a.d-b.d)[0];if(nearest?.d<16){$('pcbNet').value=nearest.p.net;api.net(nearest.p.net);$('pcbInfo').textContent=`${nearest.p.id} → ${nearest.p.net||'Sin red'} · X ${nearest.p.x.toFixed(2)} / Y ${nearest.p.y.toFixed(2)} mm`;draw();}};canvas.onpointercancel=()=>drag=null;
 canvas.ondblclick=e=>{const q=coords(e),layer=Number($('pcbLayer').value),found=b.elements.filter(e=>!!e.mirror===(layer===16)).map(el=>({el,d:Math.hypot(point(el.x,el.y)[0]-q[0],point(el.x,el.y)[1]-q[1])})).sort((a,b)=>a.d-b.d)[0];if(found?.d<45){dialog.close();onPart(found.el.name);}};
 $('pcbPlus').onclick=()=>zoomAt(1.4);$('pcbMinus').onclick=()=>zoomAt(1/1.4);$('pcbFit').onclick=()=>{zoom=1;px=py=0;draw();};$('pcbFunction').value=block;$('pcbBlocks').checked=block!=='off';$('pcbShared').checked=shared;for(const id of ['pcbLayer','pcbNet','pcbNames','pcbShared'])$(id).onchange=draw;$('pcbFunction').onchange=()=>{$('pcbBlocks').checked=$('pcbFunction').value!=='off';draw();};$('pcbBlocks').onchange=()=>{if($('pcbBlocks').checked&&$('pcbFunction').value==='off')$('pcbFunction').value='all';draw();};draw();
}
